-- ============================================
-- 005: registro de búsquedas para los reportes (mismo cambio que tables/15)
-- ============================================
CREATE TABLE IF NOT EXISTS "INFORME_BUSQUEDAS" (
    "ID_BUSQUEDA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_INFORME_BUSQUEDAS" PRIMARY KEY,
    "ID_USUARIO" INT NOT NULL CONSTRAINT "FK_INFORME_BUSQUEDAS_USUARIO" REFERENCES "USUARIOS" ("ID_USUARIO"),
    "ID_UNIDAD_EJECUTORA" INT NULL CONSTRAINT "FK_INFORME_BUSQUEDAS_UE" REFERENCES "UNIDADES_EJECUTORAS" ("ID_UNIDAD_EJECUTORA"),
    "TEXTO" VARCHAR(200) NOT NULL,
    "RESULTADOS" INT NOT NULL,
    "FECHA" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS "IX_INFORME_BUSQUEDAS_FECHA" ON "INFORME_BUSQUEDAS" ("FECHA");
